import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BaXgE4DV.js";const g=JSON.parse('{"title":"통계와 배지","description":"","frontmatter":{},"headers":[],"relativePath":"features/stats-badges.md","filePath":"features/stats-badges.md","lastUpdated":1792235115000}'),c={name:"features/stats-badges.md"};function a(s,t,i,n,l,u){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="통계와-배지" tabindex="-1">통계와 배지 <a class="header-anchor" href="#통계와-배지" aria-label="Permalink to &quot;통계와 배지&quot;">​</a></h1><p>연속일·월별 기록 수와 배지는 모두 <strong>서버에서</strong> 계산합니다. 클라이언트가 값을 조작할 수 없고, 기기 시간대와 상관없이 KST 기준으로 일관되게 계산하기 위해서입니다. → <a href="/grato-docs/decisions#adr-7">결정 기록 #7</a></p><h2 id="userstats" tabindex="-1">userStats <a class="header-anchor" href="#userstats" aria-label="Permalink to &quot;userStats&quot;">​</a></h2><p><code>userStats/{uid}</code>는 <code>onGratitudeCreated</code> 트리거의 첫 단계에서 갱신됩니다. 계산 로직은 Firebase에 의존하지 않는 순수 함수(<code>functions/src/utils/stats.ts</code>의 <code>computeNextStats</code>)라 단위 테스트로 검증합니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>의미</th></tr></thead><tbody><tr><td><code>totalGratos</code></td><td>전체 감사 수</td></tr><tr><td><code>currentStreak</code></td><td>마지막 기록일 기준 연속일</td></tr><tr><td><code>longestStreak</code></td><td>지금까지 가장 길었던 연속일(마이페이지 &quot;최대 연속일&quot;). 글을 쓸 때 <code>max(이전 값, currentStreak)</code>, 글을 지우면 남은 글로 다시 계산</td></tr><tr><td><code>thisMonthCount</code></td><td><code>monthKey</code> 달의 감사 수</td></tr><tr><td><code>lastGratoDateKey</code></td><td>마지막 기록일 <code>YYYY-MM-DD</code> (KST)</td></tr><tr><td><code>monthKey</code></td><td><code>YYYY-MM</code> (KST)</td></tr><tr><td><code>lastGratoDate</code></td><td>마지막 기록 시각</td></tr><tr><td><code>activeDays</code></td><td><strong>기록한 날</strong>: 글이 있는 KST 날짜 수(누적, 끊겨도 줄지 않음). 새 날의 첫 글이면 +1. 예전 문서는 없을 수 있음 → <a href="/grato-docs/architecture/cloud-functions#backfill-active-days">백필</a></td></tr><tr><td><code>restDays</code></td><td><strong>쉼표의 날</strong>로 이어 준 날짜 <code>[YYYY-MM-DD]</code>(오래된 순, 최근 36개) → <a href="#rest-day">쉼표의 날</a></td></tr></tbody></table><h3 id="계산-규칙-글-하나가-추가될-때" tabindex="-1">계산 규칙 (글 하나가 추가될 때) <a class="header-anchor" href="#계산-규칙-글-하나가-추가될-때" aria-label="Permalink to &quot;계산 규칙 (글 하나가 추가될 때)&quot;">​</a></h3><p>글의 <code>createdAt</code>을 KST 날짜 키로 바꿔 직전 기록일과 비교합니다.</p><table tabindex="0"><thead><tr><th>상황</th><th><code>currentStreak</code></th><th><code>thisMonthCount</code></th></tr></thead><tbody><tr><td>첫 기록</td><td>1</td><td>1</td></tr><tr><td>같은 날 또 기록</td><td>그대로</td><td>+1</td></tr><tr><td>바로 전날에 기록이 있었음</td><td>+1</td><td>같은 달이면 +1, 달이 바뀌었으면 1</td></tr><tr><td>딱 하루(어제)만 비었고 쉼표의 날을 쓸 수 있음</td><td><strong>+1</strong> (비운 날은 세지 않고 이어 줌)</td><td>같은 달이면 +1, 아니면 1</td></tr><tr><td>그 밖에 하루 이상 비었음</td><td>1로 초기화</td><td>같은 달이면 +1, 아니면 1</td></tr><tr><td>더 오래된 글이 늦게 처리됨 (순서 뒤바뀜)</td><td>그대로</td><td>같은 달이면 +1</td></tr></tbody></table><ul><li><code>totalGratos</code>는 항상 +1입니다.</li><li>트리거 전달 순서가 뒤바뀌어도 마지막 기록일이 과거로 돌아가지 않습니다.</li><li><code>lastGratoDateKey</code>가 없는 예전 문서는 <code>lastGratoDate</code>에서 KST로 날짜를 계산합니다.</li><li>같은 트랜잭션에서 <code>statsLogs/gratitude_{id}</code> 마커를 만들어, 트리거가 두 번 실행돼도 한 번만 셉니다.</li><li>트리거가 실행되기 전에 글이 이미 지워졌으면 세지 않습니다.</li></ul><h3 id="rest-day" tabindex="-1">쉼표의 날 (끊김 직후 복구) <a class="header-anchor" href="#rest-day" aria-label="Permalink to &quot;쉼표의 날 (끊김 직후 복구) {#rest-day}&quot;">​</a></h3><p>연속일이 끊긴 <strong>다음 날 하루 안에</strong> 글을 쓰면, 비운 하루를 &quot;쉼표의 날&quot;로 바꿔 연속일을 이어 줍니다. 끊긴 연속 기록이 보이기만 해도 이후 참여가 줄고, 실패 <strong>직후</strong> 쓸 수 있는 여유분이 다시 시도하게 만든다는 연구에 맞춘 장치입니다. → <a href="/grato-docs/decisions#adr-28">결정 기록 #28</a></p><ul><li><strong>서버가 정합니다.</strong> 글을 셀 때(<code>computeNextStats</code>) 직전 기록일이 그저께이고 아래 조건을 만족하면 <code>currentStreak</code>을 이어 가고 그 날을 <code>restDays</code>에 더합니다. 앱은 쓰기 전에 &quot;오늘 쓰면 n일 연속으로 이어져요&quot;라고 알려 줄 뿐 <code>userStats</code>를 쓰지 못합니다(규칙: 클라이언트 쓰기 거부).</li><li><strong>조건:</strong> 비운 날이 딱 하루, 그 전 연속일이 <code>REST_DAY_MIN_STREAK</code>(3)일 이상, 비운 날의 달(KST)에 쓴 쉼표의 날이 <code>REST_DAYS_PER_MONTH</code>(1)번 미만. 이틀 이상 비면 이어지지 않습니다.</li><li><strong>따로 누르지 않습니다.</strong> 다음 날 글을 쓰는 것이 곧 복구입니다. 미리 쌓아 두는 보호권도, 유료 판매도 없습니다.</li><li>쉼표의 날은 연속일 수에 더하지 않습니다(그 날은 쓰지 않았으므로). 3일 연속 → 하루 쉼 → 다음 날 쓰면 4일 연속.</li><li>한도 두 값은 <code>functions/src/utils/streakRest.json</code>과 <code>src/content/streakRest.json</code>에 같게 둡니다(클라이언트 테스트가 확인).</li><li>이미 쉼표의 날인 날을 다시 이을 때(다음 날 글을 지웠다가 다시 쓴 경우)는 한도를 다시 쓰지 않습니다.</li><li>글을 지워 다시 계산해도 <code>restDays</code>는 남고, 양쪽 날에 글이 있으면 계속 이어 줍니다. 그래서 복구한 연속일이 재계산으로 사라지지 않습니다.</li><li>연속 배지(<code>streak_3/7/30</code>)와 &quot;n일째 감사 중&quot;(<code>authorStreak</code>)은 이어진 연속일을 그대로 씁니다.</li></ul><h3 id="rebuild" tabindex="-1">글을 지웠을 때 <a class="header-anchor" href="#rebuild" aria-label="Permalink to &quot;글을 지웠을 때 {#rebuild}&quot;">​</a></h3><p>글은 하나씩 빼는 대신 <strong>남은 글로 다시 계산합니다</strong>(<code>onGratitudeDeleted</code> → <code>rebuildUserStats</code>). 연속일 중간의 글을 지우면 연속일이 끊길 수 있어, 빼기만으로는 정확히 맞출 수 없기 때문입니다.</p><ul><li><code>totalGratos</code>는 남은 글 수(집계 <code>count()</code>), 나머지는 남은 글의 KST 날짜와 저장된 <code>restDays</code>로 계산합니다. <code>activeDays</code>는 남은 글의 날짜 수(4,000개를 넘으면 저장된 값보다 내려가지 않음). 최대 연속일 때문에 모든 글의 날짜를 200개씩 읽습니다(최대 20쪽 = 4,000개, 그보다 많으면 최대 연속일은 저장된 값보다 내려가지 않음).</li><li>계산은 순수 함수 <code>statsFromDateKeys</code>·<code>dateKeysDecideStats</code>(<code>utils/stats.ts</code>)가 하고, 글을 하나씩 더한 결과와 같은지 단위 테스트로 확인합니다.</li><li><code>userStats</code> 문서가 있을 때만 고칩니다. 계정 삭제 뒤에 늦게 실행돼도 문서를 되살리지 않습니다.</li><li><strong>받은 배지는 유지합니다.</strong> 글을 지워 조건 아래로 내려가도 배지를 회수하지 않습니다.</li></ul><h3 id="화면-표시-규칙" tabindex="-1">화면 표시 규칙 <a class="header-anchor" href="#화면-표시-규칙" aria-label="Permalink to &quot;화면 표시 규칙&quot;">​</a></h3><p>저장된 <code>currentStreak</code>은 &quot;마지막으로 쓴 날 기준&quot; 값이라 오래 쓰지 않으면 낡은 값이 남습니다. 그래서 표시할 때 한 번 더 판단합니다(클라이언트 <code>getStatsView</code>, 서버 <code>displayStreak</code>).</p><p>홈 카드는 <strong>기록한 날(누적)을 먼저</strong> 보여 줍니다: 제목은 &quot;기록한 날 n일&quot;, 연속일은 3일째부터 옆에 작은 칩(&quot;🔥 n일 연속&quot;)으로만 붙습니다. 끊긴 연속일을 &quot;0&quot;으로 크게 보여 주지 않고, 문구는 사용자를 탓하지 않는 말로 씁니다. → <a href="/grato-docs/decisions#adr-28">결정 기록 #28</a></p><table tabindex="0"><thead><tr><th>마지막 기록일 (KST)</th><th>표시 연속일</th><th>홈 카드 문구</th></tr></thead><tbody><tr><td>오늘</td><td>저장된 값</td><td>오늘도 감사를 기록했어요! (어제가 쉼표의 날이면 &quot;어제는 쉼표의 날로 이어 두었어요&quot;)</td></tr><tr><td>어제</td><td>저장된 값</td><td>어제도 감사했어요. 오늘도 이어가볼까요?</td></tr><tr><td>그저께, 쉼표의 날을 쓸 수 있음</td><td>0 (칩 없음)</td><td>어제는 바쁜 하루였나 봐요. 오늘 쓰면 n일 연속으로 이어져요</td></tr><tr><td>그 이전</td><td>0 (칩 없음)</td><td>바쁜 날도 있죠. 기록한 날은 그대로 남아 있어요</td></tr><tr><td>기록 없음</td><td>0</td><td>첫 번째 감사를 기록해보세요!</td></tr></tbody></table><ul><li><p><code>activeDays</code>가 없는 예전 문서는 백필 전까지 제목을 &quot;나의 감사 기록&quot;으로 보여 줍니다(<code>totalGratos</code>로 짐작하지 않음).</p></li><li><p>마이페이지 숫자 칸은 <strong>기록한 날 · Grato · 최대 연속일 · Circle</strong>. 캘린더 카드의 연속일 칸은 이번 달 연속일이 이어지는 동안만, 끊겼거나 지난 달이면 그 달의 최장 연속을 보여 줍니다.</p></li><li><p><code>thisMonthCount</code>는 <code>monthKey</code>가 이번 달(KST)이 아니면 0으로 보여 줍니다.</p></li><li><p>방금 글을 쓴 세션에서는 트리거가 반영되기 전까지 <code>authStore.lastPostDateKey</code>로 오늘 기록을 미리 반영해 보여 줍니다.</p></li><li><p>홈과 MyPage는 <code>userStats</code>를 실시간 구독해 트리거 결과가 들어오면 바로 갱신됩니다.</p></li><li><p>공유 캘린더 페이지의 연속일도 서버에서 같은 규칙(<code>displayStreak</code>)으로 계산합니다.</p></li></ul><div class="info custom-block"><p class="custom-block-title">알려진 차이</p><p>MyPage 캘린더의 월 이동과 캘린더 공유 URL의 월은 아직 기기 시간대 기준입니다. 한국 밖에서 월 경계 근처에 보면 서버(KST)와 하루 차이가 날 수 있습니다.</p></div><h2 id="배지" tabindex="-1">배지 <a class="header-anchor" href="#배지" aria-label="Permalink to &quot;배지&quot;">​</a></h2><h3 id="기본-배지" tabindex="-1">기본 배지 <a class="header-anchor" href="#기본-배지" aria-label="Permalink to &quot;기본 배지&quot;">​</a></h3><p><code>badges</code> 컬렉션이 비어 있으면 첫 평가(또는 <code>seedQuestions</code> 스크립트) 때 기본 배지를 시드합니다. 비어 있지 않으면 건드리지 않으므로, 운영자가 지운 기본 배지는 다시 생기지 않습니다.</p><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>아이콘</th><th>조건</th></tr></thead><tbody><tr><td><code>gratitude_count_1</code></td><td>첫 감사</td><td>🌱</td><td>감사 1개</td></tr><tr><td><code>streak_3</code></td><td>3일 연속</td><td>🔥</td><td>연속 3일</td></tr><tr><td><code>streak_7</code></td><td>7일 연속</td><td>⚡</td><td>연속 7일</td></tr><tr><td><code>streak_30</code></td><td>30일 연속</td><td>💎</td><td>연속 30일</td></tr><tr><td><code>gratitude_count_10</code></td><td>감사 10개</td><td>🌿</td><td>감사 10개</td></tr><tr><td><code>gratitude_count_50</code></td><td>감사 50개</td><td>🌳</td><td>감사 50개</td></tr><tr><td><code>gratitude_count_100</code></td><td>감사 100개</td><td>🏆</td><td>감사 100개</td></tr><tr><td><code>circle_count_1</code></td><td>함께하기</td><td>🤝</td><td>Circle 1개 참여</td></tr></tbody></table><h3 id="question-badges" tabindex="-1">질문 배지 <a class="header-anchor" href="#question-badges" aria-label="Permalink to &quot;질문 배지 {#question-badges}&quot;">​</a></h3><p>제안한 질문이 운영자에게 선정되면 받는 단계별 배지입니다(1·3·10번째 선정). → <a href="/grato-docs/features/questions">질문 제안과 선정</a></p><ul><li>정의는 <code>functions/src/badges/questionBadges.ts</code>(<code>ensureQuestionBadges</code>)에 있습니다. 없는 배지만 배지 평가 때와 <code>seedQuestions</code> 스크립트가 만들고(<code>sortOrder</code>는 기존 배지 뒤), 이미 있는 문서는 운영자가 고친 내용을 덮어쓰지 않습니다.</li><li>이 셋은 지우면 다음 평가 때 다시 생기므로, 없애려면 <code>enabled: false</code>로 둡니다.</li><li>질문을 숨겨도 이미 받은 배지는 유지됩니다.</li></ul><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>아이콘</th><th>설명</th></tr></thead><tbody><tr><td><code>questions_selected_1</code></td><td>첫 질문 선정</td><td>💡</td><td>제안한 질문이 처음으로 선정됐어요</td></tr><tr><td><code>questions_selected_3</code></td><td>질문 큐레이터</td><td>✨</td><td>제안한 질문이 3번 선정됐어요</td></tr><tr><td><code>questions_selected_10</code></td><td>질문 장인</td><td>🏅</td><td>제안한 질문이 10번 선정됐어요</td></tr></tbody></table><h3 id="conditions" tabindex="-1">조건 종류 <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;조건 종류 {#conditions}&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>condition</code></th><th>비교 대상</th><th>계산 방법</th></tr></thead><tbody><tr><td><code>gratitude_count</code></td><td><code>userStats.totalGratos</code></td><td>통계 그대로</td></tr><tr><td><code>streak</code></td><td><code>userStats.currentStreak</code></td><td>통계 그대로</td></tr><tr><td><code>circle_count</code></td><td>실제로 멤버인 Circle 수</td><td><code>users.groupIds</code>의 각 그룹 문서를 읽어 <code>memberIds</code>에 있는 것만 셈. 글을 Circle에 공유했는지와는 상관없음</td></tr><tr><td><code>reactions_received</code></td><td>내 글들이 받은 공감</td><td>글마다 <strong>나 아닌 사람 수</strong>(한 사람이 이모지를 여러 개 눌러도 1, 내가 내 글에 누른 것은 0)를 더함 — <code>reactionsFromOthers</code></td></tr><tr><td><code>shares</code></td><td>공개한 감사 글 수</td><td><code>userId == 나 &amp;&amp; isPublic == true</code> 개수 (count 집계)</td></tr><tr><td><code>questions_selected</code></td><td>선정된 질문 수</td><td><code>authorId == 나 &amp;&amp; source == &quot;user&quot; &amp;&amp; status == &quot;approved&quot;</code> 개수 (count 집계). 숨긴 질문은 세지 않지만 이미 받은 배지는 유지</td></tr><tr><td><code>season_days</code></td><td>그 배지의 기간에 기록한 날</td><td><code>startAt</code>–<code>endAt</code> 안에 글을 쓴 <strong>KST 날짜 수</strong>(같은 날 여러 글은 1). 배지마다 자기 기간으로 셈 → <a href="#season-badges">시즌 배지</a></td></tr></tbody></table><p>조건 판단은 순수 함수 <code>badges/conditions.ts</code>(<code>meetsBadgeCondition</code>)에 있습니다. 비용이 드는 계산(<code>circle_count</code>, <code>reactions_received</code>, <code>shares</code>, <code>questions_selected</code>, <code>season_days</code>)은 <strong>아직 얻지 않은 배지 중 그 조건이 있을 때만</strong> 실행합니다.</p><h3 id="평가-시점" tabindex="-1">평가 시점 <a class="header-anchor" href="#평가-시점" aria-label="Permalink to &quot;평가 시점&quot;">​</a></h3><table tabindex="0"><thead><tr><th>시점</th><th>함수</th></tr></thead><tbody><tr><td>글을 쓸 때 (통계 갱신 직후)</td><td><code>onGratitudeCreated</code> → <code>evaluateBadges(userId)</code></td></tr><tr><td>글을 처음 공개할 때 (<code>isPublic</code> false→true)</td><td><code>onReactionUpdated</code> → <code>evaluateBadges</code> (<code>shares</code> 조건)</td></tr><tr><td>Circle을 만들거나 새로 참여할 때</td><td><code>createCircle</code>, <code>joinCircle</code> → <code>evaluateBadges</code> (<code>circle_count</code> 조건)</td></tr><tr><td>제안한 질문이 선정될 때</td><td><code>reviewQuestion</code> → <code>evaluateBadges</code> (<code>questions_selected</code> 조건)</td></tr></tbody></table><p>공감을 받는 것만으로는 평가하지 않으므로, <code>reactions_received</code> 배지는 다음 글을 쓸 때 부여됩니다.</p><h3 id="season-badges" tabindex="-1">시즌 배지 (기간에 기록한 날) <a class="header-anchor" href="#season-badges" aria-label="Permalink to &quot;시즌 배지 (기간에 기록한 날) {#season-badges}&quot;">​</a></h3><p>연말연초 같은 시즌 배지는 조건 <strong>&quot;시즌 기간에 기록한 날&quot;</strong>(<code>season_days</code>)로 만듭니다. 다른 조건은 기간과 상관없는 누적값이라, 기간을 걸어도 &quot;기간 안에 글을 한 번 쓰면&quot; 바로 받게 됩니다.</p><ul><li><strong>세는 법</strong>: 배지의 <code>startAt</code>–<code>endAt</code> 안에 쓴 글의 KST 날짜 수. 연속일이 아니라 하루 쉬어도 떨어지지 않습니다. 기간 전의 기록은 세지 않습니다(소급 없음). 순수 함수 <code>seasonWindow</code>·<code>countSeasonDays</code>·<code>seasonReadRange</code>(<code>badges/conditions.ts</code>)가 계산하고 단위 테스트로 KST 00:00 경계, 같은 날 여러 글, 첫날·마지막 날을 확인합니다.</li><li><strong>읽기</strong>: 기간 안의 아직 얻지 않은 시즌 배지가 있을 때만, 내 글(<code>userId == 나</code>)을 모든 시즌 배지 기간을 덮는 한 범위로 한 번 읽습니다(<code>createdAt</code>만, 새 글부터 최대 1,000개). 기존 <code>userId</code> + <code>createdAt</code> 인덱스를 씁니다. 기간 밖이면 평가하지 않습니다(다른 기간 배지와 같음).</li><li><strong>기간·시즌 키는 필수</strong>: <code>startAt</code>·<code>endAt</code> 중 하나라도 없으면 이 조건은 절대 맞지 않습니다. 문서 ID에 시즌 키가 들어가 <code>season_days_{값}_{seasonKey}</code>(예: <code>season_days_7_2026-winter</code>)입니다. 그래서 다음 시즌이나 누적 배지(<code>gratitude_count_7</code> 등)와 겹치지 않습니다.</li><li><strong>받은 배지는 기간 뒤에도 보입니다</strong>: 마이페이지 배지 카드는 받은 배지를 늘 보이고, 받지 않은 배지만 기간 밖에서 숨깁니다(<code>visibleBadges</code>, <code>src/lib/badgeCatalog.js</code>). 받은 배지·호칭은 회수하지 않습니다.</li><li><strong>배지 상세</strong>: 조건 줄 &quot;시즌 기간에 기록한 날 7일&quot;, 그 아래 &quot;기간 11월 15일–12월 31일&quot;(기간이 있는 모든 배지). 시즌이 시작된 뒤에는 &quot;이번 시즌에 n일 기록했어요&quot;를 정보로만 보입니다(1일 이상일 때, 내 글만 최대 500개 읽음). 홈에 &quot;다음 배지까지 n일&quot; 같은 목표는 두지 않습니다.</li><li><strong>예전 앱(1.0.1 (4) 이하)</strong>: 조건 줄에 영문 키가 그대로 보입니다(&quot;season_days 7회 이상&quot;). 기간이 끝나면 받은 시즌 배지도 목록에서 빠집니다(앱 업데이트로 고쳐짐). 지급과 호칭은 서버라 앱 버전과 상관없습니다.</li><li><strong>시즌 호칭</strong>: 호칭 가이드 7(기간 넣기)에 따라 연도를 넣고, 길이(1번, 2–7자)는 <strong>연도를 빼고</strong> 셉니다(예: &quot;2026 겨울의 마음&quot; = 6자).</li><li><strong>미리 보기</strong>: 개발 빌드의 <a href="/grato-docs/mobile/#dev-clock">테스트 날짜</a>로 기간 전·중·뒤 화면을 봅니다. 지급은 서버의 실제 시각이라, 에뮬레이터에서 기간이 오늘을 포함하는 배지를 만들어 확인합니다.</li></ul><h3 id="evaluatebadges-동작" tabindex="-1">evaluateBadges 동작 <a class="header-anchor" href="#evaluatebadges-동작" aria-label="Permalink to &quot;evaluateBadges 동작&quot;">​</a></h3><ol><li>기본 배지 시드(컬렉션이 비었을 때), 예전 배지 ID(<code>first_grato</code> 등)를 결정적 ID로 이전, 없는 질문 배지 생성</li><li><code>userStats</code>, <code>badges</code> 전체, <code>userBadges</code>, <code>users</code>를 병렬로 읽음</li><li><code>enabled !== false</code>이고 <code>startAt</code>~<code>endAt</code> 기간 안이며 아직 얻지 않은 배지만 후보</li><li>조건을 만족하는 배지를 트랜잭션으로 <code>userBadges.badges</code>에 <code>{badgeId, earnedAt}</code> 추가 — 트랜잭션 안에서 이미 가진 배지를 다시 확인해 동시 실행에도 중복 부여하지 않음. <code>users/{uid}</code>가 없으면(계정 삭제 중) 아무것도 쓰지 않음</li><li>새로 얻은 배지마다 <code>analyticsEvents</code>에 <code>badge_earned</code> 기록</li><li>켜진 보상 공감(<code>appConfig/reactionRewards</code>)의 배지를 가졌으면 같은 트랜잭션에서 <code>userBadges.reactions</code>에 그 이모지를 추가 — 새 배지가 없어도, 보상이 나중에 켜졌으면 이때 지급 → <a href="#reward-reactions">보상 공감</a></li><li>같은 트랜잭션에서 가진 배지의 호칭(<code>userBadges.titles</code>)과 이미지 테마(<code>userBadges.themes</code>)도 더함 — 배지에 나중에 달렸으면 다음 평가 때 → <a href="#titles">호칭</a>, <a href="#themes">이미지 테마</a></li><li>이번에 센 서버 집계 숫자(<code>reactions_received</code>, <code>shares</code>, <code>circle_count</code>, <code>questions_selected</code> 중 아직 얻지 않은 배지가 쓰는 것)를 <code>userBadges.progress</code>에 저장 — 앱의 &quot;다음 배지까지 n&quot;용. 숫자가 바뀌었을 때만 씀 → <a href="#next-badge">다음 배지</a></li></ol><p><code>badges</code>를 조회할 때 <code>where(&#39;enabled&#39;, ...)</code>를 쓰지 않는 이유는 <code>enabled</code> 필드가 없는 문서가 쿼리에서 빠지기 때문입니다.</p><h2 id="reward-reactions" tabindex="-1">배지 보상: 공감 이모지 <a class="header-anchor" href="#reward-reactions" aria-label="Permalink to &quot;배지 보상: 공감 이모지 {#reward-reactions}&quot;">​</a></h2><p>누구나 쓰는 공감 4개(❤️ 🙏 ✨ 🔥)에 더해, 배지를 얻은 사람만 쓰는 <strong>보상 공감 이모지</strong>가 있습니다(다시 쓰게 하는 보상). 처음에는 모두 꺼져 있고, 운영자가 켤 때부터 지급됩니다.</p><table tabindex="0"><thead><tr><th>이모지</th><th>이름</th><th>받는 배지</th></tr></thead><tbody><tr><td>🌸</td><td>벚꽃</td><td>7일 연속 (<code>streak_7</code>)</td></tr><tr><td>🍀</td><td>네잎클로버</td><td>감사 50개 (<code>gratitude_count_50</code>)</td></tr><tr><td>🌈</td><td>무지개</td><td>30일 연속 (<code>streak_30</code>)</td></tr></tbody></table><ul><li><strong>화면</strong>: 공감 고르기 창에 기본 4개 다음으로 켜진 보상이 나옵니다. 받은 것은 그대로 고르고, 아직 못 받은 것은 흐리게 자물쇠와 함께 보이며 누르면 &quot;🍀 &#39;감사 50개&#39; 배지를 받으면 쓸 수 있어요&quot;. 누군가 남긴 보상 공감은 모두에게 보입니다(꺼진 뒤에도).</li><li><strong>지급</strong>: <code>evaluateBadges</code>가 켜진 보상의 배지를 가진 사람의 <code>userBadges.reactions</code>에 이모지를 넣습니다. 한 번 받은 보상은 꺼도 남습니다(새 지급과 고르기 창에서만 빠짐).</li><li><strong>규칙</strong>: 보상 이모지를 <strong>추가</strong>할 때만 <code>userBadges/{uid}.reactions</code>를 읽어(get 1회) 받은 사람인지 확인합니다. 빼기는 누구나 자기 것만. 허용 이모지 목록은 규칙에 고정되어 있습니다(<code>rewardReactionEmojis</code>).</li><li><strong>목록은 세 곳에 같게</strong>: <code>src/content/reactionRewards.json</code>(앱), <code>functions/src/badges/reactionRewards.json</code>(서버), <code>firestore.rules</code>의 <code>rewardReactionEmojis</code>와 <code>reactionOk</code> 줄. <code>src/content/reactions.test.js</code>가 셋이 같은지 확인합니다.</li></ul><h3 id="reward-reactions-ops" tabindex="-1">보상 켜기·더하기 <a class="header-anchor" href="#reward-reactions-ops" aria-label="Permalink to &quot;보상 켜기·더하기 {#reward-reactions-ops}&quot;">​</a></h3><ul><li><strong>켜기</strong>(목록에 있는 것): <code>node lib/scripts/setupReactionRewards.js --enable 🌸 --dry-run</code> → <code>--enable 🌸</code>. <code>appConfig/reactionRewards</code>에 켜고, 이미 그 배지를 가진 사람에게 바로 지급합니다. 앱 업데이트는 필요 없습니다(앱이 켜진 목록을 읽음).</li><li><strong>끄기</strong>: <code>--disable 🌸</code>. 받은 사람은 그대로 씁니다.</li><li><strong>새 보상 더하기</strong>: 위 세 곳에 한 줄씩(이모지·배지·배지 이름) → 테스트 → 함수·규칙 배포 → 웹 배포·앱 새 빌드(새 이모지를 고르기 창에 보이려면) → <code>--enable</code>.</li><li>현황: 옵션 없이 실행하면 보상별 켜짐 여부와 가진 사람 수를 보여 줍니다.</li></ul><h2 id="titles" tabindex="-1">배지 보상: 호칭 <a class="header-anchor" href="#titles" aria-label="Permalink to &quot;배지 보상: 호칭 {#titles}&quot;">​</a></h2><p>배지에 <strong>호칭</strong>을 달 수 있습니다(관리자 › 배지 › &quot;호칭&quot;). 그 배지를 얻은 사람은 호칭을 받고, 마이페이지 <strong>&quot;이름 꾸미기&quot;</strong> 에서 하나를 골라 이름 옆에 붙입니다(글·댓글·글 상세의 이름 옆에 작은 칩). 처음에는 어느 배지에도 호칭이 없습니다.</p><ul><li><strong>시즌 호칭</strong>: 기간(<code>startAt</code>~<code>endAt</code>)이 있는 배지에 호칭을 달면, 그 기간에 배지를 얻은 사람만 받습니다. <strong>어려운 호칭</strong>: 조건이 높은 배지에 답니다.</li><li><strong>지급</strong>: <code>evaluateBadges</code>가 가진 배지의 호칭을 <code>userBadges.titles</code>에 넣습니다(새 배지가 없어도 배지에 호칭이 새로 달렸으면 다음 평가 때). 한 번 받은 호칭은 남습니다 — 배지의 호칭을 고치면 새 호칭이 더해지고 예전 것도 계속 고를 수 있습니다.</li><li><strong>고르기</strong>: <code>publicProfiles/{uid}.title</code>(없으면 null). 규칙이 <code>userBadges.titles</code>에 있는 것만 허용합니다(바꿀 때만 get 1회). 고르거나 바꾸면 지난 글·댓글의 이름 옆도 바뀝니다(<a href="/grato-docs/architecture/cloud-functions#author-sync">작성자 표시 맞추기</a>).</li><li>배지 상세 시트에 &quot;보상 호칭 …&quot;이 보여, 아직 못 받은 배지도 무엇을 주는지 알 수 있습니다.</li><li>모두의 감사방에서도 별명 옆에 보입니다(별명 글의 <code>authorTitle</code>도 규칙이 프로필의 호칭과 같은지 확인).</li></ul><h3 id="title-guide" tabindex="-1">호칭 가이드 <a class="header-anchor" href="#title-guide" aria-label="Permalink to &quot;호칭 가이드 {#title-guide}&quot;">​</a></h3><p>배지에 호칭을 달기 전에 확인합니다. <strong>한 번 지급된 호칭은 문구를 고쳐도 사용자에게 남으므로</strong> 처음 문구가 사실상 영구적입니다.</p><ol><li><strong>2~7자.</strong> 글·댓글의 이름 옆 작은 칩에 연속일 태그와 함께 한 줄로 들어가야 합니다(입력 상한 20자는 기술적 한도).</li><li><strong>명사형.</strong> 끝이 명사인 짧은 말(예: 고마움 수집가, 한 달의 마음). &quot;~하는&quot;, &quot;~한&quot;으로 끝내지 않습니다.</li><li><strong>하루 만에 얻는 배지에는 달지 않습니다.</strong> 첫 감사, 첫 공감, 첫 댓글처럼 바로 얻는 배지는 배지와 축하만 줍니다. 호칭은 1주 안팎 걸리는 배지부터 답니다.</li><li><strong>서열·게임 말 금지.</strong> 장인, 마스터, 킹, 레전드, 레벨, 숫자 등급, 영어 섞기, &quot;~러&quot; 같은 유행어, 과하게 귀여운 말투. 호칭끼리 높낮이 없이 모으는 것으로 둡니다.</li><li><strong>연속일 태그와 다른 말.</strong> &quot;🔥 n일째 감사 중&quot;은 지금 이어가는 중임을, 호칭은 한 번 이뤄낸 것을 말합니다.</li><li><strong>같은 길은 같은 말로 잇습니다.</strong> 연속은 &quot;이어진 ~&quot;, 받은 공감은 &quot;~마음·울림·온기&quot;처럼 한 길의 호칭이 한 가족으로 보이게 합니다.</li><li><strong>시즌 호칭에는 기간을 넣습니다</strong>(예: 2026 겨울의 마음).</li><li><strong>모두의 감사방에서도 보입니다.</strong> 받은 사람이 아주 적을 호칭은 별명 뒤의 사람을 짐작하게 할 수 있으니 조건을 너무 좁히지 않습니다.</li></ol><p>지금 있는 조건의 단계와 호칭입니다(호칭 &quot;—&quot;은 배지와 축하만).</p><table tabindex="0"><thead><tr><th>조건</th><th>단계 · 호칭</th></tr></thead><tbody><tr><td>연속 (<code>streak</code>)</td><td>3 · — / 7 · 이어진 일주일 / 30 · 이어진 한 달</td></tr><tr><td>감사 개수 (<code>gratitude_count</code>)</td><td>1 · — / 10 · — / 50 · 고마움 수집가 / 100 · 백 개의 고마움</td></tr><tr><td>받은 공감 (<code>reactions_received</code>)</td><td>3 · — / 10 · 닿는 마음 / 30 · 다정한 울림 / 100 · 모두의 온기</td></tr><tr><td>질문 선정 (<code>questions_selected</code>)</td><td>1 · 질문 새싹 / 3 · 좋은 질문가 / 10 · 질문의 길잡이</td></tr><tr><td>링크로 공개한 감사 (<code>shares</code>)</td><td>1 · — / 10 · 건네는 마음 / 30 · 열린 마음</td></tr><tr><td>Circle 함께하기 (<code>circle_count</code>)</td><td>1 · —</td></tr></tbody></table><p>받은 공감 배지는 관리자 › 배지에서 조건 &quot;받은 공감&quot;으로 만듭니다(ID는 <code>reactions_received_{값}</code>). 다른 사람이 공감할 수 있는 건 Circle 글(모두의 감사방 포함)뿐이라 거기서만 쌓이고(링크 공개 페이지에서는 공감할 수 없음), 다음 글을 쓸 때 평가됩니다. 셈을 고친 함수를 배포한 <strong>뒤에</strong> 만듭니다 — 먼저 만들면 예전 셈(내 공감·이모지 개수 포함)으로 지급되고, 지급된 배지는 회수하지 않습니다.</p><h2 id="themes" tabindex="-1">배지 보상: 이미지 테마 <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;배지 보상: 이미지 테마 {#themes}&quot;">​</a></h2><p>배지에 <strong>이미지 테마</strong>를 달 수 있습니다(관리자 › 배지 › &quot;이미지 테마&quot;: 없음·겨울·신년). 그 배지를 얻은 사람은 기기에서 만드는 이미지 — 캘린더, 배지, 감사 글, 초대장 — 를 그 테마로 그릴 수 있습니다. 시즌 배지 = 시즌 호칭(기간 포함) + 테마입니다. → <a href="/grato-docs/decisions#adr-37">ADR-37</a></p><table tabindex="0"><thead><tr><th>테마</th><th>id</th><th>모습</th></tr></thead><tbody><tr><td>기본</td><td><code>default</code></td><td>따뜻한 크림 배경, 장식 없음. 누구나</td></tr><tr><td>겨울</td><td><code>winter</code></td><td>눈빛 파랑, 눈 결정과 눈 언덕</td></tr><tr><td>신년</td><td><code>newyear</code></td><td>새벽 하늘(라벤더→살구)과 해돋이</td></tr></tbody></table><ul><li><strong>지급</strong>: <code>evaluateBadges</code>가 가진 배지의 <code>badges/{id}.theme</code>을 <code>userBadges.themes</code>에 받은 순서대로 넣습니다(호칭과 같은 방식, <code>functions/src/badges/themes.ts</code>). 한 번 받은 테마는 배지에서 테마를 빼도 남습니다. 배지에 테마를 달지 않으면 아무에게도 지급되지 않으므로, 앱 업데이트 없이 끄는 방법이기도 합니다.</li><li><strong>고르기</strong>: 이미지 시트(<code>ImageShareSheet</code>)의 테마 칩에 <strong>받은 테마만</strong> 보입니다. 잠긴 테마·가격 표시는 없고, 기본만 가진 사람에게는 칩 자체가 없습니다. 처음에는 가장 최근에 받은 테마, 그다음부터는 이 기기에서 마지막으로 고른 테마(브라우저 저장소, 없으면 다시 가장 최근 것). 서버에 저장하지 않으므로 규칙 쓰기 경로가 없습니다.</li><li><strong>배지 상세</strong>: 받은 배지에만 &quot;받은 테마 겨울 · 이미지에 쓸 수 있어요&quot;가 보입니다(못 받은 배지에는 테마를 보이지 않음).</li><li><strong>규칙</strong>: <code>badges/{id}.theme</code>은 없거나 null이거나 <code>imageThemeIds()</code>(겨울·신년) 중 하나(운영자 쓰기). <code>userBadges</code>는 서버만 씁니다.</li><li><strong>목록은 세 곳에 같게</strong>: <code>src/lib/themes.js</code>(앱, 색 토큰), <code>functions/src/badges/themes.json</code>(서버), <code>firestore.rules</code>의 <code>imageThemeIds()</code>. <code>src/lib/themes.test.js</code>가 셋이 같은지와 모든 글자 색이 바탕 위에서 AA(4.5:1)인지 확인합니다.</li><li><strong>예전 앱</strong>: 1.0.1 (4) 이하 앱과 테마 id를 모르는 앱은 테마를 읽지 않고 기본 모습으로 그립니다(<code>getTheme</code>이 모르는 id는 기본). 테마 고르기는 iOS 1.0.1 (5) 앱과 웹부터입니다.</li><li><strong>새 테마 더하기</strong>: 세 곳에 id를 더하고 <code>themes.js</code>에 토큰·장식 → 테스트 → 함수·규칙 배포 → 웹 배포·앱 새 빌드 → 배지에 테마 달기. 앱이 모르는 테마를 먼저 지급하면 그 앱에서는 보이지 않을 뿐 남아 있다가 새 앱에서 보입니다.</li></ul><h3 id="theme-images" tabindex="-1">이미지 <a class="header-anchor" href="#theme-images" aria-label="Permalink to &quot;이미지 {#theme-images}&quot;">​</a></h3><p>모두 기기 안에서 캔버스로 그립니다(<code>src/lib/themeCanvas.js</code>의 공통 도구, 360px 배치를 3배로 그려 가로 1080px). 장식은 고정 좌표라 같은 내용이면 늘 같은 이미지입니다. 이미지를 만들어도 링크 공개 설정(<code>isPublic</code>, <code>publicShares</code>)은 바뀌지 않습니다.</p><table tabindex="0"><thead><tr><th>이미지</th><th>어디서</th><th>크기</th><th>들어가는 것</th></tr></thead><tbody><tr><td>캘린더</td><td>마이페이지 캘린더 카드의 저장 버튼</td><td>1080 × 약 1240–1500</td><td>그 달의 기록한 날·연속일·달력(<code>calendarImage.js</code>). 시즌 테마는 위에 30px 장식 띠와 카드 테두리가 더해짐</td></tr><tr><td>감사 글</td><td>글 상세 › &quot;이미지&quot; (작성자만, 검토 중인 글 제외)</td><td>1080 × 1350</td><td>제목 2줄, 본문 6줄(넘치면 &quot;…&quot;), 작성자 이름(글에 보이는 이름), 날짜(KST)</td></tr><tr><td>배지</td><td>배지 상세 › &quot;이미지로 간직하기&quot; (받은 배지, 공유 가능한 배지만)</td><td>1080 × 1350</td><td>아이콘·이름·설명, 호칭이 있으면 호칭, &quot;{이름}님 · 받은 날&quot;</td></tr><tr><td>초대장</td><td>Circle 설정 › 초대 › &quot;초대장 이미지로 보내기&quot;</td><td>1080 × 1350</td><td>초대한 사람, Circle 이름. <strong>초대 코드는 넣지 않음</strong> — 공유하면 초대 메시지(링크·코드)가 이미지와 함께 가서, 받는 사람은 그 링크로 들어옵니다</td></tr></tbody></table><p>4:5 틀(<code>startFramedImage</code>·<code>finishFramedImage</code>, <code>src/lib/shareImages.js</code>)은 다른 이미지(올해의 감사 돌아보기, GRATO-73)도 씁니다. 앱은 네이티브 공유 시트(사진에 저장 포함), 웹은 &quot;이미지 저장&quot;(내려받기)과, 파일 공유를 지원하는 브라우저면 &quot;공유하기&quot;. 기록은 <code>image_shared {kind, theme, method}</code>.</p><h3 id="hide-streak" tabindex="-1">연속일 숨기기 <a class="header-anchor" href="#hide-streak" aria-label="Permalink to &quot;연속일 숨기기 {#hide-streak}&quot;">​</a></h3><p>설정의 <strong>연속일 숨기기</strong>(<code>users.hideStreak</code>, 기본 꺼짐)를 켜면 연속일을 어디에도 보이지 않고 기록한 날만 보여 줍니다: 홈 카드 칩·문구, 마이페이지 최대 연속일·캘린더 연속일 칸과 저장 이미지, 홈 화면 위젯(요약본의 <code>streak</code>을 0으로 써서 &quot;감사 기록&quot;), 캘린더 공유 페이지, 이름 옆 &quot;n일째 감사 중&quot;(<code>stampStreak</code>이 건너뜀). 서버의 연속일 계산과 연속 배지는 그대로입니다.</p><h2 id="show-streak" tabindex="-1">연속 감사 보여주기 <a class="header-anchor" href="#show-streak" aria-label="Permalink to &quot;연속 감사 보여주기 {#show-streak}&quot;">​</a></h2><p>마이페이지 &quot;이름 꾸미기&quot;의 <strong>연속 감사 보여주기</strong>를 켜면(<code>users.showStreak</code>), 새로 쓰는 글의 이름 옆에 그날의 연속일이 <strong>&quot;🔥 12일째 감사 중&quot;</strong> 으로 보입니다.</p><ul><li>서버가 글을 셀 때(통계 직후) 그 글에 <code>authorStreak</code>를 씁니다. 클라이언트는 이 필드를 쓸 수 없어 꾸밀 수 없습니다. 끄면 그 뒤 글부터 찍히지 않습니다(이미 찍힌 글은 그대로).</li><li>글을 쓴 날의 값이라 이후에 연속이 끊겨도 그 글은 그대로입니다. 댓글에는 붙지 않습니다.</li><li>모두의 감사방 글에도 찍힙니다.</li></ul><h2 id="배지-관리-관리자" tabindex="-1">배지 관리 (관리자) <a class="header-anchor" href="#배지-관리-관리자" aria-label="Permalink to &quot;배지 관리 (관리자)&quot;">​</a></h2><p><code>/admin</code> 페이지의 &quot;배지&quot; 탭에서 배지를 만들고 고칩니다(첫 탭은 <a href="/grato-docs/features/questions#review">질문 검토</a>). <code>users/{uid}.isAdmin == true</code>인 사용자만 내용이 보이고, 규칙도 같은 조건으로 <code>badges</code> 쓰기를 허용합니다. <code>isAdmin</code>은 Firebase 콘솔 또는 Admin SDK로만 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td>이름·설명·아이콘</td><td>표시 정보</td></tr><tr><td>조건·기준값</td><td>위의 7가지 조건 중 하나</td></tr><tr><td><code>badgeType</code></td><td>기본(<code>core</code>), 월간(<code>monthly</code>), 기간 한정(<code>limited</code>), 소셜(<code>social</code>)</td></tr><tr><td><code>seasonKey</code></td><td>시즌 구분 (기본 외 유형). <code>season_days</code>는 필수(영어 소문자·숫자·<code>-</code>, 20자 이내, 문서 ID에 들어감)</td></tr><tr><td><code>startAt</code>, <code>endAt</code></td><td>활성 기간. 관리자 화면에서 KST 날짜로 고르면 첫날 00:00–마지막 날 23:59:59.999로 저장. 밖이면 평가하지 않고, 받지 않은 사람에게는 보이지 않음(받은 사람에게는 계속 보임). <code>season_days</code>는 필수</td></tr><tr><td><code>shareable</code></td><td>공유 가능 여부</td></tr><tr><td><code>enabled</code></td><td>끄면 평가·표시하지 않음</td></tr><tr><td><code>sortOrder</code></td><td>표시 순서 (위·아래 이동)</td></tr></tbody></table><ul><li>조건 선택지에 &quot;선정된 질문 수&quot;(<code>questions_selected</code>)가 있습니다.</li><li>새 배지의 문서 ID는 <code>{condition}_{conditionValue}</code>, <code>season_days</code>만 <code>season_days_{conditionValue}_{seasonKey}</code>입니다(<code>badgeIdFor</code>). 같은 ID의 배지가 이미 있으면 만들 수 없습니다. ID가 정해지므로 시즌 배지는 만든 뒤 조건과 시즌 키를 바꿀 수 없습니다(이름·기간·호칭은 고칠 수 있음).</li><li>조건 &quot;시즌 기간에 기록한 날&quot;을 고르면 유형이 기간 한정으로 바뀌고 기간·시즌 키 입력이 나옵니다.</li><li>이미 부여된 배지는 정의를 꺼도 <code>userBadges</code>에서 지워지지 않습니다.</li></ul><h2 id="배지-표시와-공유" tabindex="-1">배지 표시와 공유 <a class="header-anchor" href="#배지-표시와-공유" aria-label="Permalink to &quot;배지 표시와 공유&quot;">​</a></h2><p>MyPage 배지 카드는 얻은 배지를 먼저, 나머지를 흐리게 보여 주고 <code>얻은 수/보이는 수</code>를 표시합니다. 기간이 있는 배지는 받았으면 늘, 받지 않았으면 기간 안에만 보입니다(<a href="#season-badges">시즌 배지</a>). 그 아래 한 줄에 가장 가까운 <a href="#next-badge">다음 배지</a>가 작게 보입니다(기간 밖의 받지 않은 시즌 배지는 고르지 않음). 배지를 누르면 상세 시트에서 획득일과 공유 버튼이 나옵니다. 공유하면 <code>publicShares/{uid}.badgeIds</code>에 추가되어 공유 페이지에 이름과 획득 여부가 보입니다. → <a href="/grato-docs/features/gratitudes#sharing">외부 공유</a></p><h2 id="celebration" tabindex="-1">배지 축하 <a class="header-anchor" href="#celebration" aria-label="Permalink to &quot;배지 축하 {#celebration}&quot;">​</a></h2><p>배지를 얻으면 호칭이 있든 없든 한 번, 조용한 축하 카드가 뜹니다(GRATO-18). 두 개 이상이 한꺼번에 들어오면 &quot;그동안 모은 배지 n개&quot; 한 장으로 모읍니다(GRATO-19). 화면 시안·움직임은 디자인 결과(GRATO-41 v2)를 따릅니다. → <a href="/grato-docs/decisions#adr-29">결정 기록 #29</a></p><p><strong>언제 뜨나</strong></p><ul><li>앱이 <code>userBadges/{uid}</code>를 지켜보다가 <code>users/{uid}.badgesSeenAt</code>보다 늦게 받은 배지(<code>earnedAt</code>)가 보이면 띄웁니다. 배지 평가는 글을 쓴 뒤 서버에서 몇 초 걸리므로 보통 홈으로 돌아온 뒤입니다.</li><li>홈·마이페이지·Circle·글 상세·저장한 감사·공지·설정에서만 띄웁니다. 글 쓰는 중(<code>/write</code>), 동의 화면, 계정 삭제, 공개 페이지에서는 기다립니다. 다른 시트·대화상자가 열려 있거나 탭이 숨겨져 있어도 기다렸다가, 화면이 1초쯤 가만히 있으면 띄웁니다.</li><li>한 번에 한 장. 카드가 열려 있는 동안 또 배지가 들어오면 닫은 뒤 다음 장으로 띄웁니다.</li><li>저절로 사라지지 않습니다. 닫기·확인·Esc·뒤로 가기(웹은 기록 한 칸, Android는 뒤로 버튼)·배경 탭으로 닫습니다.</li></ul><p><strong>한 번만 (본 배지 기록)</strong></p><ul><li><code>users/{uid}.badgesSeenAt</code>(본인이 쓰는 시각)은 축하한 배지 중 가장 늦은 <code>earnedAt</code>입니다. <strong>카드가 열리는 순간</strong> 이 기기(<code>localStorage</code>)와 계정에 함께 적어, 다른 기기에서도 다시 뜨지 않고 중간에 앱을 닫아도 다시 뜨지 않습니다.</li><li>띄우기 전에 서버에서 이 값을 한 번 더 읽습니다(기기 캐시가 낡아 다른 기기가 이미 축하한 배지를 또 띄우지 않게). 새 배지가 없으면 읽지 않습니다.</li><li>계정에 쓰지 못하면(오프라인 등) 기기 기록이 남아 그 기기에서는 다시 뜨지 않습니다. 기기 저장까지 막힌 브라우저에서는 계정 기록만 씁니다.</li><li><strong>기준선:</strong> 이 값이 없는 계정은 축하 기능이 들어간 앱으로 처음 열 때 기준선을 정합니다. 만든 지 24시간이 넘은 계정은 지금 가진 배지 중 가장 늦은 시각(업데이트 뒤 모달이 쏟아지지 않음), 24시간 안의 새 계정은 0(첫 배지부터 축하). 기준선은 서버에서 받은 <code>userBadges</code>로만 정합니다(낡은 기기 캐시로 정하지 않음).</li><li>규칙: 시각(timestamp)만, 미래 시각 금지, 앞으로만 이동. → <a href="/grato-docs/architecture/security-rules">보안 규칙</a></li></ul><p><strong>무엇을 보여 주나</strong></p><table tabindex="0"><thead><tr><th>부분</th><th>내용</th></tr></thead><tbody><tr><td>라벨·아이콘</td><td>&quot;새 배지&quot;, 배지 아이콘(묶음은 64px 아이콘이 80ms 간격으로 놓이고 아래에 이름, 6개부터 &quot;외 n개&quot;)</td></tr><tr><td>이름·설명</td><td>배지 이름과 한 줄 설명. 묶음은 &quot;그동안 모은 배지 n개&quot; / &quot;그동안의 기록이 모여 배지가 되었어요&quot;</td></tr><tr><td>호칭</td><td>호칭이 있으면 &quot;이름 옆에 이렇게 보여요&quot; + 내 이름 + 호칭 칩. 묶음은 <strong>가장 최근 호칭 하나</strong>(받은 시각 → 같은 길의 높은 단계 → <code>sortOrder</code> 순)만, 나머지는 &quot;함께 받은 … 마이페이지에서 고를 수 있어요&quot;</td></tr><tr><td>보상 공감</td><td>이 배지로 받은 보상 이모지가 있으면 &quot;보상 공감 · 벚꽃 / 이제 공감할 때 🌸를 고를 수 있어요&quot;</td></tr><tr><td>다음 배지</td><td>같은 길의 다음 단계, 혼자 길 배지였다면 함께 길에서 가장 가까운 배지 → <a href="#next-badge">다음 배지</a></td></tr><tr><td>주 버튼</td><td>호칭이 있으면 &quot;이름 옆에 붙이기&quot;(바로 <code>publicProfiles.title</code>을 바꿈 → &quot;이름 옆에 붙였어요&quot;), 이미 붙어 있거나 호칭이 없으면 &quot;확인&quot;</td></tr><tr><td>보조 버튼</td><td>공유하기(가장 최근 배지, 지금의 배지 공유 페이지) · 닫기</td></tr><tr><td>회고</td><td>오늘(KST) 쓴 내 감사가 홈 피드에 있으면 &quot;오늘 쓴 감사 다시 보기&quot;</td></tr></tbody></table><p><strong>연출</strong> (<code>components/badges/celebration.css</code>, 약 1.2초, 입자는 2.4초에 끝, 반복 없음): 배경 흐림 240ms → 카드 8px 상승·96→100% 360ms(120ms부터) → 금빛 고리 600ms(300ms) → 빛줄기 700ms(400ms) → 라벨·이름·설명 40ms 간격(500ms) → 입자 10개(묶음 11개) 1.3초씩(800ms부터) → 호칭·보상·다음 배지·버튼(900ms). 폭죽·이모지 비·흔들림·소리 없음. 앰버(<code>#F59E0B</code>·<code>#FBBF24</code>)는 고리·입자에만, 주 버튼은 <code>primary</code> 토큰.</p><ul><li><strong>움직임 줄이기</strong>(<code>prefers-reduced-motion: reduce</code>, 앱은 기기 설정): 배경·카드는 opacity만, 고리·빛줄기·입자는 그리지 않고 글자·버튼은 카드와 함께 나타납니다.</li><li><strong>접근성</strong>: <code>role=&quot;dialog&quot;</code>(이름 = 배지 이름), 열리면 카드로 포커스, Tab은 카드 안에서만, 닫으면 원래 자리로. 버튼은 44px 이상.</li><li><strong>앱</strong>: 카드가 자리 잡는 480ms에 가벼운 진동 1회(<code>lib/native/haptics.js</code>, <code>@capacitor/haptics</code>, 움직임 줄이기와 상관없이).</li></ul><p><strong>시작을 막지 않음 (ADR-13)</strong>: 축하 코드(<code>BadgeCelebration</code>·<code>CelebrationModal</code>·CSS)는 따로 나뉜 코드이고, 첫 화면이 뜨고 브라우저가 한가해진 뒤(+1.5초) 불러옵니다. <code>userBadges</code> 구독도 그때 시작합니다. 동의가 필요한 계정에서는 띄우지 않습니다.</p><h2 id="next-badge" tabindex="-1">다음 배지 <a class="header-anchor" href="#next-badge" aria-label="Permalink to &quot;다음 배지 {#next-badge}&quot;">​</a></h2><p>&quot;다음 배지 · 보름의 마음까지 8일&quot;처럼 다음 목표를 <strong>작게, 보조로</strong> 보여 줍니다(GRATO-20). 배지가 글을 쓰는 이유가 되지 않도록 화면의 주인공으로 두지 않습니다.</p><table tabindex="0"><thead><tr><th>어디</th><th>무엇</th></tr></thead><tbody><tr><td>축하 카드</td><td>같은 길의 다음 단계 + (혼자 길 배지였다면) 함께 길에서 가장 가까운 배지, 두 줄</td></tr><tr><td>홈 기록 카드</td><td>혼자 길(기록한 날·연속·감사 개수) 중 가장 가까운 배지 한 줄</td></tr><tr><td>마이페이지 배지 카드</td><td>모든 길 중 가장 가까운 배지 한 줄</td></tr></tbody></table><ul><li><strong>숫자의 출처</strong>: 감사 개수·연속일·기록한 날은 <code>userStats</code>(연속일은 화면 규칙 그대로 끊겼으면 0), 받은 공감·공개한 글·Circle·선정 질문은 서버가 배지를 평가할 때 저장한 <code>userBadges.progress</code>. 숫자를 모르는 조건(아직 세지 않은 새 조건 등)은 보여 주지 않습니다(짐작하지 않음). 서버가 세는 새 조건을 더하면 <code>functions/src/badges/progress.ts</code>의 <code>SERVER_COUNTED_CONDITIONS</code>에도 넣어야 줄이 보입니다.</li><li><strong>가장 가까운</strong> = 남은 양이 가장 적은 것, 같으면 길 순서(기록한 날 → 연속 → 감사 개수 → 함께 길).</li><li><strong>문구</strong>: 같은 길은 &quot;다음 배지 · {호칭 또는 배지 이름}까지 n{일·개·번}&quot;, 함께 길은 조건마다 &quot;친구 글에 공감 3번이면 다정한 이웃&quot;, &quot;공감 3개를 더 받으면 닿는 마음&quot;, &quot;Circle에 첫 감사를 나누면 …&quot; 식(<code>lib/badgeCelebration.js</code> <code>goalText</code>). 비교·순위 말은 쓰지 않습니다.</li><li><strong>진행 막대</strong>: 다섯 칸짜리 작은 막대. 지금까지 한 것(누적)이 이미 채워져 있어 1–2칸 찬 채로 시작합니다(endowed progress). 아무것도 없으면 그리지 않고, 배지를 받기 전에는 다 채우지 않습니다.</li><li><strong>축하 뒤 흐름</strong>: 다음 목표는 글로만 두고 누르는 버튼을 만들지 않습니다. 카드의 행동은 호칭 붙이기·공유하기(나누기)와 &quot;오늘 쓴 감사 다시 보기&quot;(회고)입니다. 보상 직후 이탈이 몰린다는 연구(근거 보고서) 때문입니다.</li></ul><h2 id="year-review" tabindex="-1">올해의 감사 돌아보기 <a class="header-anchor" href="#year-review" aria-label="Permalink to &quot;올해의 감사 돌아보기 {#year-review}&quot;">​</a></h2><p>연말연초 시즌(기본 <strong>12/1–1/31 KST</strong>)에 마이페이지 맨 위에 &quot;{연도}년 돌아보기&quot; 카드가 나옵니다. 올해 내가 고마움을 적은 날을 정보로 비춰 주는 회고이고, <strong>나만 봅니다</strong>. 다른 사람·평균과 비교, 순위, 받은 공감 수는 없습니다. 숫자는 문장 안에서 본문 크기로만 씁니다. → <a href="/grato-docs/decisions#adr-38">결정 기록 #38</a></p><table tabindex="0"><thead><tr><th>화면</th><th>내용</th></tr></thead><tbody><tr><td>카드 (<code>YearReviewCard</code>)</td><td>&quot;올해 n일, 고마움을 적었어요.&quot; + 달마다 점 12칸(그달에 하루라도 썼는지만). 1–6일이면 &quot;적어 둔 n일이 올해의 기록이에요. 쉬어 간 날도 괜찮아요.&quot;를 더함. 누르면 펼친 화면</td></tr><tr><td>0일</td><td>카드 대신 &quot;올해의 마지막 감사로 시작해 볼까요?&quot; + 오늘의 질문 + &quot;이 질문으로 쓰기&quot;</td></tr><tr><td>펼친 화면 <code>/mypage/year</code></td><td>첫 문장, 달마다 적은 날(요일 맞춘 점), 올해 처음 쓴 감사의 날짜(누르면 그 글), &quot;다시 읽어 볼 감사&quot; 최대 3개(서로 다른 달, 누르면 글), &quot;올해를 돌아보는 질문으로 쓰기&quot;, &quot;이미지로 간직하기&quot;</td></tr><tr><td>이미지로 간직하기</td><td>4:5 PNG(1080×1350): &quot;{연도}년 돌아보기&quot;, 달 12칸(썼는지만), 아래 줄. <strong>기본은 숫자 없음</strong>, &quot;기록한 날 넣기&quot;를 켜야 &quot;올해 n일&quot;이 들어감(열 때마다 꺼짐). 감사 글 제목·내용은 넣지 않음. 웹은 저장(+ 지원하면 공유), 앱은 공유 시트. 받은 테마로 그림</td></tr></tbody></table><p><strong>계산 (기기 안).</strong> <code>src/lib/yearReview.js</code>(순수, <code>yearReview.test.js</code>)가 계산하고 <code>src/lib/yearReviewData.js</code>가 읽습니다. 서버 집계를 새로 만들지 않습니다.</p><ul><li>읽기: <code>gratitudes</code>에서 <code>userId == 나</code>, 그 연도의 KST 달마다 한 번(마이페이지 캘린더와 같은 쿼리 모양, 달마다 최대 500개). 시작한 달까지만 읽습니다. 메모리에는 화면에 필요한 필드(<code>id</code>, 시각, KST 날짜, 제목, 본문 첫 줄 80자, 숨김 여부)만 둡니다.</li><li>지난달은 세션 동안 기억하고 이번 달은 열 때마다 다시 읽습니다. 글을 지우면 기억한 달을 잊습니다(<code>forgetYearReview</code>). 오프라인 캐시만 있고 글이 없으면 &quot;0일&quot;이 아니라 불러오기 실패로 봅니다.</li><li>날짜는 KST: 12/31 23:30 KST 글은 그해, 1/1 00:10 KST 글은 다음 해입니다.</li><li>숨김(검토 중) 글: 작성자에게는 보이므로 기록한 날·처음 쓴 감사에는 셉니다. &quot;다시 읽어 볼 감사&quot;에는 넣지 않습니다.</li><li>&quot;다시 읽어 볼 감사&quot;: 숨기지 않은 글이 있는 달 가운데 그날(KST 날짜)로 정해지는 3달에서 하나씩, 날짜 순. 같은 날에는 늘 같은 글이고 날이 바뀌면 바뀝니다. 나만 보기 글도 포함합니다(이 화면은 나만 봄).</li></ul><p><strong>켜고 끄기.</strong> <code>appConfig/yearReview = { enabled?, start?: &#39;MM-DD&#39;, end?: &#39;MM-DD&#39; }</code>(KST). 문서가 없거나 읽지 못하면 앱 기본값(켜짐, 12-01..01-31)입니다. 새해를 넘는 기간(시작 &gt; 끝)은 시작한 해를 돌아봅니다(1월에는 지난해). 감사 시즌은 11/15에 시작하고, 돌아보기는 연말 단계인 12/1부터입니다. 웹은 앱과 따로 배포되므로 앱 출시가 늦어도 웹에서는 12/1에 켜집니다. 앱 업데이트 없이 끄거나 날짜를 옮길 수 있습니다 → <a href="/grato-docs/operations/deploy#year-review">운영: 올해 돌아보기 켜고 끄기</a>. 설정은 마이페이지를 열 때 세션에 한 번 읽고, 시작 경로에서는 읽지 않습니다(ADR-13). 설정을 읽기 전에는 기본 기간으로 판단해 자리(불러오는 중)를 먼저 보이고, 꺼져 있으면 사라집니다.</p><p><strong>질문으로 쓰기.</strong> 오늘의 질문(<code>todayQuestion</code>, KST)으로 &quot;질문으로 쓰기&quot;를 엽니다. 시즌 질문(GRATO-72)이 들어오면 그 기간에는 시즌 질문이 오늘의 질문이 됩니다. 뒤로 가면 돌아보기 화면으로 돌아옵니다. 새 글은 기본 &quot;나만 보기&quot;입니다.</p><p><strong>테마.</strong> 다른 이미지와 같은 시트(<code>ImageShareSheet</code>)와 틀(<code>startFramedImage</code>/<code>finishFramedImage</code>)을 씁니다. 받은 테마만 고를 수 있고(기본은 늘, 잠금·가격 표시 없음), 처음에는 이 기기에서 마지막에 고른 테마 또는 가장 최근에 받은 테마입니다 → <a href="#themes">이미지 테마</a>.</p><p><strong>이용 기록</strong> (<code>analyticsEvents</code>, 글 내용 없음): <code>year_review_card_viewed</code>(세션에 한 번, <code>year</code>, <code>tier</code>: zero/few/full), <code>year_review_opened</code>, <code>year_review_write</code>(<code>from</code>: card/page), 이미지는 다른 이미지와 같은 <code>image_shared</code>(<code>kind: &#39;year_review&#39;</code>, <code>theme</code>, <code>method</code>, <code>year</code>, <code>withDays</code>).</p><p><strong>넣지 않는 곳.</strong> 홈 화면 위젯(ADR-18), 공유 페이지·서버. 웹·앱 모두 같은 화면입니다.</p><p><strong>날짜 바꿔 보기 (개발 빌드만).</strong> <code>npm run dev</code>(또는 <code>VITE_DEV_CLOCK=true</code> 기기 확인 빌드)에서는 왼쪽 아래 🕒로 KST 날짜를 옮겨 카드를 볼 수 있습니다(<code>src/lib/devClock.js</code>, 시즌 배지 GRATO-71과 같은 도구). 돌아보기는 그 날짜로 기간·연도·&quot;다시 읽어 볼 감사&quot;를 정합니다. 일반 <code>npm run build</code>(웹 배포·스토어 빌드)에는 없고, Hosting predeploy(<code>scripts/checkNoDevClock.js</code>)가 그런 빌드의 배포를 막습니다.</p>',101)])])}const q=e(c,[["render",a]]);export{g as __pageData,q as default};
